-- RPC implementation for 0004. Every write for one owner takes the same row lock;
-- cursor order is therefore commit order, not client-clock order.
create or replace function public.sync_library(p_owner_id uuid, p_op_id uuid, p_snapshot jsonb) returns jsonb language plpgsql security invoker as $$
declare cached jsonb; item jsonb; c bigint; result jsonb := jsonb_build_object('documents','[]'::jsonb,'nodes','[]'::jsonb,'versions','[]'::jsonb,'conflicts','[]'::jsonb);
begin
 if auth.uid() is null or auth.uid() <> p_owner_id then raise exception 'owner mismatch'; end if;
 select result into cached from public.sync_operations where owner_id=auth.uid() and op_id=p_op_id; if cached is not null then return cached; end if;
 insert into public.sync_cursors(owner_id) values(auth.uid()) on conflict do nothing; perform 1 from public.sync_cursors where owner_id=auth.uid() for update;
 for item in select * from jsonb_array_elements(coalesce(p_snapshot->'nodes','[]')) loop
   insert into public.library_nodes(id,owner_id,parent_id,kind,name,sort_order,song,rev,deleted_at,created_at,updated_at) values((item->>'id')::uuid,auth.uid(),nullif(item->>'parentId','')::uuid,item->>'kind',item->>'name',(item->>'order')::bigint,item->'song',(item->>'rev')::bigint,nullif(item->>'deletedAt','')::timestamptz,to_timestamp((item->>'createdAt')::double precision/1000),to_timestamp((item->>'updatedAt')::double precision/1000)) on conflict(id) do update set parent_id=excluded.parent_id,name=excluded.name,sort_order=excluded.sort_order,song=excluded.song,rev=excluded.rev,deleted_at=excluded.deleted_at,updated_at=excluded.updated_at where library_nodes.owner_id=auth.uid() and library_nodes.rev=excluded.rev-1;
   update public.sync_cursors set value=value+1 where owner_id=auth.uid() returning value into c; insert into public.sync_changes values(auth.uid(),c,'node',item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id)); result:=jsonb_set(result,'{nodes}',(result->'nodes')||jsonb_build_array(item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id)));
 end loop;
 for item in select * from jsonb_array_elements(coalesce(p_snapshot->'documents','[]')) loop
   insert into public.documents(id,owner_id,node_id,song_id,type,title,payload,rev,deleted_at,created_at,updated_at) values((item->>'id')::uuid,auth.uid(),nullif(item->>'nodeId','')::uuid,nullif(item->>'songId','')::uuid,item->>'type',item->>'title',item->'content',(item->>'rev')::bigint,nullif(item->>'deletedAt','')::timestamptz,to_timestamp((item->>'createdAt')::double precision/1000),to_timestamp((item->>'updatedAt')::double precision/1000)) on conflict(id) do update set node_id=excluded.node_id,song_id=excluded.song_id,title=excluded.title,payload=excluded.payload,rev=excluded.rev,deleted_at=excluded.deleted_at,updated_at=excluded.updated_at where documents.owner_id=auth.uid() and documents.rev=excluded.rev-1;
   update public.sync_cursors set value=value+1 where owner_id=auth.uid() returning value into c; insert into public.sync_changes values(auth.uid(),c,'document',item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id)); result:=jsonb_set(result,'{documents}',(result->'documents')||jsonb_build_array(item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id)));
 end loop;
 for item in select * from jsonb_array_elements(coalesce(p_snapshot->'versions','[]')) loop insert into public.document_versions(id,owner_id,document_id,reason,title,payload,created_at) values((item->>'id')::uuid,auth.uid(),(item->>'documentId')::uuid,item->>'reason',item->>'title',item->'content',to_timestamp((item->>'createdAt')::double precision/1000)) on conflict(id) do nothing; update public.sync_cursors set value=value+1 where owner_id=auth.uid() returning value into c; insert into public.sync_changes values(auth.uid(),c,'version',item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id)); result:=jsonb_set(result,'{versions}',(result->'versions')||jsonb_build_array(item||jsonb_build_object('ownerId',auth.uid(),'lastOpId',p_op_id))); end loop;
 insert into public.sync_operations(owner_id,op_id,result) values(auth.uid(),p_op_id,result); return result;
end $$;
create or replace function public.pull_library(p_owner_id uuid,p_after text,p_limit int default 100) returns jsonb language plpgsql security invoker as $$ declare rows jsonb; max_cursor bigint; begin if auth.uid() is null or auth.uid()<>p_owner_id then raise exception 'owner mismatch'; end if; select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'record',record) order by cursor),'[]') into rows from (select * from public.sync_changes where owner_id=auth.uid() and cursor>(p_after::bigint) order by cursor limit greatest(1,least(p_limit,500))) q; select coalesce(max(cursor),p_after::bigint) into max_cursor from public.sync_changes where owner_id=auth.uid() and cursor>(p_after::bigint) and cursor<=coalesce((select max(cursor) from public.sync_changes where owner_id=auth.uid()),p_after::bigint); return jsonb_build_object('cursor',max_cursor::text,'changes',rows,'hasMore',false); end $$;
